def loop_starts(fuel, burn):
    n = len(fuel)
    gain = [f - b for f, b in zip(fuel, burn)]
    if sum(gain) < 0:
        return []
    first, tank = 0, 0
    for i in range(n):
        tank += gain[i]
        if tank < 0:
            first, tank = i + 1, 0
    starts = []
    for s in list(range(first, n)) + list(range(first)):
        tank = 0
        for k in range(n):
            tank += gain[(s + k) % n]
            if tank < 0:
                break
        else:
            starts.append(s)
    return sorted(starts)
